CREATE OR REPLACE FUNCTION public.delete_global_store(p_admin_id text, p_store_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1
    from public.employees e
    where e.id::text = btrim(p_admin_id)
      and lower(btrim(coalesce(e.role::text,'')))
          in ('admin','أدمن','ادمن')
      and coalesce(e.is_active,true) = true
  ) then
    raise exception 'Not authorized to manage global stores';
  end if;

  delete from public.global_stores
  where id = p_store_id;

  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_global_store(p_admin_id text, p_store_id bigint, p_name text, p_logo_url text, p_category text, p_store_url text, p_sort_order integer DEFAULT 0)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id bigint;
begin
  if not exists (
    select 1 from public.employees e
    where e.id::text=btrim(p_admin_id)
      and lower(btrim(coalesce(e.role::text,''))) in ('admin','أدمن','ادمن')
      and coalesce(e.is_active,true)=true
  ) then
    raise exception 'Not authorized to manage global stores';
  end if;

  if p_store_id is null then
    raise exception 'Store id is required';
  end if;

  if btrim(coalesce(p_name,''))='' or btrim(coalesce(p_store_url,''))='' then
    raise exception 'Store name and URL are required';
  end if;

  if coalesce(p_category,'') not in (
    'comprehensive',
    'fashion',
    'sports',
    'beauty',
    'home'
  ) then
    raise exception 'Invalid store category';
  end if;

  update public.global_stores
  set name=btrim(p_name),
      logo_url=btrim(coalesce(p_logo_url,'')),
      category=p_category,
      store_url=btrim(p_store_url),
      sort_order=coalesce(p_sort_order,0),
      is_active=true,
      updated_at=now()
  where id=p_store_id
  returning id into v_id;

  if v_id is null then
    raise exception 'Global store not found';
  end if;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_set_exchange_rate(p_store_id uuid, p_rate numeric, p_base_currency text, p_target_currency text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_rate is null or p_rate <= 0 then
    raise exception 'Exchange rate must be greater than zero';
  end if;

  update public.local_stores
  set exchange_rate = p_rate,
      exchange_base_currency = nullif(trim(p_base_currency), ''),
      exchange_target_currency = nullif(trim(p_target_currency), '')
  where id = p_store_id;

  if not found then
    raise exception 'Store not found';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_set_profit_margin(p_store_id text, p_margin numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                                    DECLARE
                                                                                                      v_margin NUMERIC;
                                                                                                      BEGIN
                                                                                                        IF p_margin IS NULL
                                                                                                             OR p_margin < 0
                                                                                                                  OR p_margin > 10000
                                                                                                                    THEN
                                                                                                                        RAISE EXCEPTION
                                                                                                                              'Profit margin must be between 0 and 10000 percent';
                                                                                                                                END IF;

                                                                                                                                  UPDATE public.local_stores
                                                                                                                                    SET profit_margin_percent = p_margin
                                                                                                                                      WHERE id::text = p_store_id
                                                                                                                                        RETURNING profit_margin_percent INTO v_margin;

                                                                                                                                          IF NOT FOUND THEN
                                                                                                                                              RAISE EXCEPTION 'Store not found';
                                                                                                                                                END IF;

                                                                                                                                                  RETURN v_margin;
                                                                                                                                                  END;
                                                                                                                                                  $function$
